import java.math.BigDecimal;
import java.math.RoundingMode;

public final class CurrencyCalculator {

    // Always define standard rounding and scale for financial calculations
    private static final int FINANCIAL_SCALE = 2;
    private static final RoundingMode DEFAULT_ROUNDING = RoundingMode.HALF_EVEN;

    public static BigDecimal calculateTotal(String basePriceStr, String taxRateStr) {
        // CRITICAL: Always use String constructor, never new BigDecimal(double)
        BigDecimal basePrice = new BigDecimal(basePriceStr);
        BigDecimal taxRate = new BigDecimal(taxRateStr);

        BigDecimal taxAmount = basePrice.multiply(taxRate)
                                      .setScale(FINANCIAL_SCALE, DEFAULT_ROUNDING);

        return basePrice.add(taxAmount).setScale(FINANCIAL_SCALE, DEFAULT_ROUNDING);
    }
}
